class Storage{constructor(e){this.tg=e,this.storage=e.CloudStorage}async getItem(e){return new Promise(((r,t)=>{this.storage.getItem(e,((s,o)=>{s?(console.error(`Storage: getItem(${e}) error:`,s),t(s)):r(o||null)}))}))}async setItem(e,r){return new Promise(((t,s)=>{this.storage.setItem(e,r,((r,o)=>{r?(console.error(`Storage: setItem(${e}) error:`,r),s(r)):t()}))}))}async getItems(e){return new Promise(((r,t)=>{this.storage.getItems(e,((e,s)=>{e?(console.error("Storage: getItems error:",e),t(e)):r(s||{})}))}))}async setItems(e){const r=Object.entries(e).map((([e,r])=>this.setItem(e,r)));return Promise.all(r)}async removeItem(e){return new Promise(((r,t)=>{this.storage.removeItem(e,((s,o)=>{s?(console.error(`Storage: removeItem(${e}) error:`,s),t(s)):r()}))}))}async removeItems(e){return new Promise(((r,t)=>{this.storage.removeItems(e,((e,s)=>{e?(console.error("Storage: removeItems error:",e),t(e)):r()}))}))}async getKeys(){return new Promise(((e,r)=>{this.storage.getKeys(((t,s)=>{t?(console.error("Storage: getKeys error:",t),r(t)):e(s||[])}))}))}async clear(){const e=await this.getKeys();return this.removeItems(e)}async hasItem(e){return null!==await this.getItem(e)}async getJSON(e){const r=await this.getItem(e);if(!r)return null;try{return JSON.parse(r)}catch(r){return console.error(`Storage: getJSON(${e}) parse error:`,r),null}}async setJSON(e,r){try{const t=JSON.stringify(r);return this.setItem(e,t)}catch(r){throw console.error(`Storage: setJSON(${e}) stringify error:`,r),r}}}